import React, { Fragment, useState, useEffect } from 'react';
import { connect, useDispatch, useSelector } from 'react-redux';
import { getAllOrders, submitOrderSettings, getOrderDetail } from '../Actions/Order';
import {
	Table,
	Button,
	Space,
	Form,
	Image,
	// Input,
	Drawer,
	Col,
	Row,
	Select,
	Checkbox,
	Typography,
	Skeleton,
	Input,
} from 'antd';
import addKeysToList from '../Utilities/addKey';

const { Option } = Select;
const { Span } = Typography;
function OrderSettingsComponent(props) {
	const [loading, setLoading] = useState(true);
	const [loadOrder, setLoadOrder] = useState(false);
	const [state, setState] = useState({
		filteredInfo: null,
		sortedInfo: null,
		selectedRowKeys: [],
		visible: false,
	});
	const [selectedOrderDetail, setselectedOrderDetail] = useState({
		date: null,
		price: null,
	});
	const {ordersPagination} = useSelector(state => state);
	const [pagination, setPagination] = useState({
		current: 1,
		pageSize:50,
		total:ordersPagination?.total,
		search: null,
		isSearched: 0,
		status:null
	});
	const [formError, setFormError] = useState('');
	const dispatch = useDispatch();

	useEffect(() => {

		if (!props.orders || props.orders === null || props.orders === undefined) {
			//props.getAllOrders(props.token);
			dispatch(getAllOrders(props.token, pagination.current, pagination.pageSize));
		}

		if (props.orders !== null && props.orders !== undefined) {
			setLoading(false);
			setPagination({
				...pagination,
				total: ordersPagination?.total,
				isSearched:pagination.isSearched+1
			})
		}

		// eslint-disable-next-line
	}, [ordersPagination]);

	const showOrderDetails = async (id, order) => {
		setLoadOrder(true);
		props.getOrderDetail(id, setselectedOrderDetail, setLoadOrder, props.token);

		
		setState({
			...state,
			visible: true,
		});

		setselectedOrderDetail({
			...selectedOrderDetail,
			...order,
			order_id: id,
		});
		setTimeout(() => {
			setLoadOrder(false);
		}, 5000);
	};

	const onClose = () => {
		setState({
			...state,
			visible: false,
		});
	};

	

	const handleChange = (pagination, filters, sorter) => {

		setPagination({
			...pagination,
			current: pagination.current,
			pageSize: pagination.pageSize
		})
		setLoading(true);
		dispatch(getAllOrders(props.token, pagination.current, pagination.pageSize, pagination.search))

		setState({
			filteredInfo: filters,
			sortedInfo: sorter,
		});
	};

	const onSelectChange = selectedRowKeys => {
		setState({ ...state, selectedRowKeys });
	};

	const { selectedRowKeys } = state;
	const rowSelection = {
		selectedRowKeys,
		onChange: onSelectChange,
	};
	const orderSearch = () => {
		setLoading(true)
		dispatch(getAllOrders(props.token, pagination.current, pagination.pageSize, pagination.search, pagination.status))	
	}

	const resetOrders = (value) => {
		if(value<1){
			value = '';
		}
		setPagination({
			...pagination,
			search: value
		})
		if(value.length == 0 && pagination.isSearched != null){
			setLoading(true)	
			dispatch(getAllOrders(props.token, pagination.current, pagination.pageSize, '', pagination.status))	
		}

	}

	const handleKeyDown = (event) => {
		if (event.key === 'Enter' && pagination.search) {
			orderSearch()
		}
	}

	const filterByOrderStatus = (status) =>{
		setLoading(true)
		setPagination({
			...pagination,
			status : status
		})	
		dispatch(getAllOrders(props.token, pagination.current, pagination.pageSize, pagination.search, status))
	}

	let { sortedInfo /* filteredInfo */ } = state;
	sortedInfo = sortedInfo || {};
	// filteredInfo = filteredInfo || {};

	const columns = [
		{
			title: 'Order Id',
			dataIndex: 'id',
			key: 'id',
			sorter: (a, b) => a.id - b.id,
			sortOrder: sortedInfo.columnKey === 'id' && sortedInfo.order,
			ellipsis: true,
		},
		{
			title: 'Customer Name',
			dataIndex: 'customer',
			key: 'customer',
		},
		{
			title: 'Date Created',
			dataIndex: 'date_created',
			key: 'date_created'
		},
		{
			title: 'Items',
			dataIndex: 'items_total',
			key: 'items_total',
			sorter: (a, b) => a.items_total - b.items_total,
			sortOrder: sortedInfo.columnKey === 'items_total' && sortedInfo.order,
			ellipsis: true,
		},
		{
			title: 'Status',
			dataIndex: 'status',
			key: 'status'
		},
		
		{
			title: 'Price',
			dataIndex: 'total_inc_tax',
			key: 'total_inc_tax',
			/*sorter: (a, b) => +a.total_inc_tax.substring(1) - +b.total_inc_tax.substring(1),
			sortOrder: sortedInfo.columnKey === 'total_inc_tax' && sortedInfo.order,
			ellipsis: true,*/
		},
		{
			title: 'Action',
			dataIndex: 'id',
			key: 'id',
			render: (id, record) => (
				<Space size='middle'>
					<Button onClick={() => showOrderDetails(id, record)}>Shipping Detail</Button>
				</Space>
			),
		},
	];

	//This is for filter form
	/* const onFinish = values => {
		console.log('Received values of form: ', values);
	}; */

	if (loading) {
		return <Skeleton active />;
	}

	return (
		<Fragment>
			<Row gutter={24} className='mb-3'>
				<Col span={8}>
					<Input
						placeholder='Search by order id'
						className='col-8'
						type='number'
						value={pagination.search}
						onKeyDown={handleKeyDown}
						onChange={ (e) => 
							
							resetOrders( e.target.value)
							/*dispatch({
								type: 'FILTER_ORDERS',
								payload: e.target.value,
							})*/
						}
						size='medium'
					/>
				</Col>
				<Col span={4} style={{paddingLeft:"0px"}}>
					<Button 
					onClick={orderSearch} 
					type='primary'
					size='medium'
					>
						Search
					</Button>
				</Col>
				<Col span={4}>
					<h3 style={{padding: '3px 0px'}} className={'text-right'}>Filter by order status</h3>
				</Col>
				<Col span={8}>	
					<Select
						placeholder='Filter by order status'
						onChange={val =>
							filterByOrderStatus(val)
						}
						size='medium'
						style={{ width: '100%' }}
						value={pagination.status}
					>
						<Option value=''>All</Option>
						<Option value='7'>Awaiting Payment</Option>
						<Option value='8'>Awaiting Pickup</Option>
						<Option value='9'>Awaiting Shipment</Option>
						<Option value='10'>Completed</Option>
						<Option value='11'>Awaiting Fulfillment</Option>
						<Option value='12'>Manual Verification Required</Option>
						<Option value='13'>Disputed</Option>
						<Option value='14'>Partially Refunded</Option>
						<Option value='0'>Incomplete</Option>
						<Option value='1'>Pending</Option>
						<Option value='2'>Shipped</Option>
						<Option value='3'>Partially Shipped</Option>
						<Option value='4'>Refunded</Option>
						<Option value='5'>Cancelled</Option>
						<Option value='6'>Declined</Option>
					</Select>
				</Col>
			</Row>
			<Table
				className='custom-table'
				//rowSelection={rowSelection}
				columns={columns}
				dataSource={props.filteredOrders ?? props.orders}
				//dataSource={addKeysToList(props.filteredOrders ?? props.orders, 1)}
				onChange={handleChange}
				pagination={pagination}
			/>

			{/* ================ */}
			<Drawer
				title={`Additional Order Details ${
					!loadOrder ? ' (' + selectedOrderDetail?.id + ')' : ''
				}`}
				width={720}
				onClose={onClose}
				visible={state.visible}
				bodyStyle={{ paddingBottom: 80 }}
				footer={
					<div
						style={{
							textAlign: 'right',
						}}
					>
						
					</div>
				}
			>
				{loadOrder ? (
					<Skeleton active />
				) : (
					<Form layout='vertical' hideRequiredMark initialValues={selectedOrderDetail}>
						<Row gutter={24} className='mb-3 float-left'>
						{
							props?.orderwidget?.widget.map( (widget, key) => (
								<Fragment>
								<Button type="primary" className={'mt-2 mb-2'} block> Shipment {key+1} </Button>

									<Col span={12}>	
										
										<div span={12}>
											<h3>Origin and Services</h3>
											<ul>
											<li>{widget?.locationtype} : {widget?.address}</li>
											<li>{widget?.shipping_method} : {widget?.shipping_rate}</li>
											{
												widget?.accessories.map((access) => (
													<li>{access}</li>
												) )
											}
											</ul>
										</div>
									</Col>
									<Col span={12}>
										<div>
											<h3>Items</h3>
											<ul>
											{
												widget?.items.map((item) => (
													<li>{item}</li>
												) )
											}
											</ul>
										</div>
									</Col>
									<Col span={24}>
										<Row gutter={24}>
											<Col span={24} style={{textAlign : 'center'}}>
												<img src={widget?.sbs?.image_complete} style={{margin: '10px'}} /><br/>
												<span>{widget?.sbs?.w}{widget?.sbs?.h}{widget?.sbs?.d}</span><br/>	
											</Col>
											<Col span={24}>
											<Row gutter={24}>
												{widget?.sbs?.type !== 'item'? 
													(widget?.sbs?.items.map((box) => (
													<>
														<Col span={6} style={{textAlign : 'center'}}>
															<img src={box?.image_sbs} style={{margin: '5px'}} /><br/>
															<span>{box?.w+'x'}{box?.h+'x'}{box?.d}</span><br/>
														</Col>
														
													</>
													) ))
													:
													''	
												}
											</Row>
											</Col>
											
										</Row>
									</Col>
									</Fragment>
							))
						}
						</Row>
								
							
					</Form>
				)}
			</Drawer>
			{/* ================ */}
		</Fragment>
	);
}

const mapStateToProps = state => {
	return {
		orders: state.orders,
		token: state.token,
		dropships: state.dropships,
		filteredOrders: state.filteredOrders,
		orderwidget: state.orderwidget,
	};
};

const mapDispatchToProps = dispatch => {
	return {
		//getAllOrders: token => dispatch(getAllOrders(token)),
		getOrderDetail: (id, setselectedOrderDetail, setLoadOrder, token) => dispatch(getOrderDetail(id, setselectedOrderDetail, setLoadOrder, token)),
		submitOrderSettings: (data, token, visibility) =>
			dispatch(submitOrderSettings(data, token, visibility)),
	};
};

export default connect(mapStateToProps, mapDispatchToProps)(OrderSettingsComponent);
